(()=>{'use strict';const trigger=document.querySelector('#deskSearch'),header=document.querySelector('main>header');if(!trigger||!header)return;const date=document.querySelector('#deskDate'),account=header.querySelector('.header-tools');if(date&&account){const keepDate=()=>{const person=account.querySelector('.shared-user');if(person){if(date.nextElementSibling!==person)account.insertBefore(date,person)}else if(account.firstElementChild!==date)account.prepend(date)};keepDate();new MutationObserver(keepDate).observe(account,{childList:true})}const box=document.createElement('div');box.id='headerSearchBox';box.className='header-search-box';box.hidden=false;box.innerHTML='<span aria-hidden="true">⌕</span><input type="search" id="headerTaskSearch" placeholder="جست‌وجوی کار، مسئول یا همکار…" aria-label="جست‌وجوی کارها" autocomplete="off"><button type="button" aria-label="بستن جست‌وجو">×</button>';box.querySelector('span').innerHTML='<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/></svg>';header.append(box);const anchor=document.createComment('search-field');box.before(anchor);const modal=document.createElement('dialog');modal.className='header-search-modal';modal.dataset.ownDismiss='true';modal.setAttribute('aria-label','جست‌وجوی کارها');modal.innerHTML='<div class="search-modal-heading"><strong id="searchModalTitle">جست‌وجو در کارها</strong><span>نام کار، مسئول یا همکار را بنویسید</span></div>';modal.setAttribute('aria-labelledby','searchModalTitle');document.body.append(modal);modal.addEventListener('cancel',e=>{e.preventDefault();close()});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});const results=document.createElement('div');results.className='search-suggestions';results.id='headerSearchSuggestions';results.setAttribute('aria-label','پیشنهادهای جست‌وجو');const resultStatus=document.createElement('p');resultStatus.className='search-result-status';resultStatus.setAttribute('role','status');modal.append(resultStatus,results);const input=box.querySelector('input'),closeButton=box.querySelector('button');input.setAttribute('aria-controls',results.id);input.setAttribute('aria-describedby','headerSearchHint');modal.querySelector('.search-modal-heading span').id='headerSearchHint';let timer;function target(){return document.querySelector('#personalSearch,#sharedSearch,#claritySearch')}function prepare(){if(target())return true;const personal=!!window.SAMANDIS_PERSONAL_MODE,nav=document.querySelector('[data-desk-view="'+(personal?'mine':'all')+'"]');nav?.click();return !!target()}function open(){if(header.classList.contains('header-search-open'))return;if(!prepare())return;input.value=target()?.value||'';box.hidden=false;const r=box.getBoundingClientRect();modal.insertBefore(box,resultStatus);modal.style.setProperty('--search-top',Math.max(16,r.top||48)+'px');modal.style.setProperty('--search-center',Math.max(Math.min(640,innerWidth-32)/2+16,Math.min(innerWidth-Math.min(640,innerWidth-32)/2-16,r.left+r.width/2||innerWidth/2))+'px');modal.showModal();suggest();document.documentElement.classList.add('search-modal-open');header.classList.add('header-search-open');trigger.setAttribute('aria-expanded','true');input.focus()}function close(reset=false){if(reset){input.value='';clearTimeout(timer);timer=null;apply()}clearTimeout(timer);if(timer){timer=null;apply()}box.hidden=false;modal.close();anchor.after(box);document.documentElement.classList.remove('search-modal-open');header.classList.remove('header-search-open');trigger.setAttribute('aria-expanded','false');input.blur();trigger.focus()}function suggest(){results.replaceChildren();const host=document.querySelector('#sharedApp,#workspace');if(!host)return;const seen=new Set(),items=[];for(const b of host.querySelectorAll('[data-task],[data-shared-card],[data-personal-edit]')){const id=b.dataset.task||b.dataset.sharedCard||b.dataset.personalEdit;if(seen.has(id))continue;seen.add(id);const row=b.closest('.personal-task-row,tr,.desk-task-card');let meta={};try{meta=JSON.parse(row?.dataset.taskSort||'{}')}catch{}const task=typeof tasks!=='undefined'?tasks.find(t=>t.id===id):null;items.push({id,title:meta.title||task?.title||b.textContent.trim(),owner:meta.owner||(task&&typeof person==='function'?person(task.owner_id):''),node:b})}const query=input.value.trim();resultStatus.textContent=query?(items.length?items.length.toLocaleString('fa-IR')+' کار مرتبط در این بخش':'کاری با این عبارت پیدا نشد.'): 'برای شروع تایپ کنید؛ کارهای این بخش';for(const item of items.slice(0,8)){const b=document.createElement('button');b.type='button';b.className='search-suggestion';const glyph=document.createElement('span');glyph.className='search-suggestion-icon';glyph.textContent='↗';glyph.setAttribute('aria-hidden','true');const text=document.createElement('span'),title=document.createElement('strong'),sub=document.createElement('small');title.textContent=item.title;sub.textContent=item.owner||'مشاهدهٔ اطلاعات کار';text.append(title,sub);b.append(glyph,text);b.onclick=()=>{close();item.node.click()};b.onkeydown=e=>{const buttons=[...results.querySelectorAll('button')],i=buttons.indexOf(b);if(e.key==='ArrowDown'){e.preventDefault();buttons[(i+1)%buttons.length]?.focus()}if(e.key==='ArrowUp'){e.preventDefault();if(i===0)input.focus();else buttons[i-1]?.focus()}if(e.key==='Escape'){e.preventDefault();close()}};results.append(b)}if(items.length>8){const more=document.createElement('small');more.className='search-more-hint';more.textContent='برای پیشنهادهای دقیق‌تر، عبارت بیشتری بنویسید.';results.append(more)}}function apply(){const original=target();if(!original)return;const focused=document.activeElement===input,pos=input.selectionStart;original.value=input.value;original.dispatchEvent(new Event('input',{bubbles:true}));suggest();if(focused){input.focus();if(pos!==null&&input.type==='text')input.setSelectionRange(pos,pos)}}trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-controls',box.id);trigger.setAttribute('aria-expanded','false');trigger.onclick=open;input.addEventListener('focus',open);closeButton.onclick=()=>close();input.oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>{timer=null;apply()},160)};input.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();results.querySelector('button')?.focus()}if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Enter'){e.preventDefault();clearTimeout(timer);timer=null;apply()}};document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!document.querySelector('dialog[open]')&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)&&!e.target.isContentEditable){e.preventDefault();e.stopImmediatePropagation();open()}},true);document.addEventListener('pointerdown',e=>{if(header.classList.contains('header-search-open')&&!box.contains(e.target)&&!modal.contains(e.target)&&!trigger.contains(e.target)){close()}});})();
